  // shipped_late(O) :- lineitem(O,_,_,_,_,_,_,_,Ship,_,_,_,_), Ship > 19950315.
  (function() {
    return _.flatten(map(function(e1) {
      var O = e1.t[0];
      var Ship = e1.t[8];
      if (Ship > 19950315) {
        return [['shipped_late', [O], e1.v]];
      } else {
        return [];
      }
    }, _.values(lineitem)));
  })()
